def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, (int, type(None))):
        raise TypeError("maxsize must be an integer or None")
    if maxsize is not None and maxsize < 0:
        raise ValueError("maxsize must be >= 0 or None")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    # If maxsize is 0 or None, no caching is performed
    if maxsize == 0 or maxsize is None:
        def decorator(func):
            return func
        return decorator

    def decorator(func):
        cache = {}
        order = []  # list of keys, oldest first, newest last

        def _make_key(args, kwargs):
            key = args
            if kwargs:
                # sort keyword items to ensure consistent ordering
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                # include types of positional arguments
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            try:
                key = _make_key(args, kwargs)
            except TypeError:
                # Unhashable arguments; do not cache
                return func(*args, **kwargs)

            if key in cache:
                # Move key to the end to mark it as most recent
                order.remove(key)
                order.append(key)
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)

            # Evict the most recently used item if cache is full
            if len(order) > maxsize:
                # MRU eviction: remove the last item (most recent)
                evict_key = order.pop()
                del cache[evict_key]

            return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__annotations__ = getattr(func, "__annotations__", {})
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
