    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError("maxsize must be an integer or None")
    if maxsize is not None and maxsize < 0:
        raise ValueError("maxsize must be >= 0")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorating_function(user_function):
        cache = {}
        order = []  # list of keys in LRU order

        def make_key(args, kwargs):
            if typed:
                args_key = tuple((arg, type(arg)) for arg in args)
                kwargs_key = tuple(sorted((k, (v, type(v))) for k, v in kwargs.items()))
            else:
                args_key = args
                kwargs_key = tuple(sorted(kwargs.items()))
            return (args_key, kwargs_key)

        def wrapper(*args, **kwargs):
            # No caching if maxsize is 0
            if maxsize == 0:
                return user_function(*args, **kwargs)

            key = make_key(args, kwargs)

            if key in cache:
                # Move key to the end to mark it as recently used
                order.remove(key)
                order.append(key)
                return cache[key]

            # Compute the result and cache it
            result = user_function(*args, **kwargs)
            cache[key] = result
            order.append(key)

            # Evict least recently used item if cache is too large
            if maxsize is not None and len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]

            return result

        return wrapper

    return decorating_function

