def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        raise TypeError("classes must be an iterable of classes")
    try:
        iterator = iter(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of classes")
    result = []
    for base in iterator:
        if not isinstance(base, type):
            raise TypeError(f"Expected a class, got {type(base).__name__}")
