    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Ensure separator is a string
    try:
        sep = str(separator)
    except Exception:
        sep = ","

    # Prepare header if provided
    lines = []
    if header is not None:
        try:
            lines.append(str(header))
        except Exception:
            lines.append("")

    # Retrieve points from the graph; raise a clear error if missing
    try:
        points = getattr(self, "points", None)
        if points is None:
            raise AttributeError("Graph object has no 'points' attribute")
    except Exception as exc:
        raise AttributeError("Unable to access graph points: %s" % exc)

    # Iterate over points and build CSV lines
    for point in points:
        # Default handling: point may be (coord, value) or just coord
        coord = None
        value = None
        if isinstance(point, (list, tuple)):
            if len(point) == 2:
                coord, value = point
            else:
                coord = point
        else:
            coord = point

        # Convert coordinate to string
        if isinstance(coord, (list, tuple)):
            try:
                coord_str = sep.join(str(c) for c in coord)
            except Exception:
                coord_str = ""
        else:
            try:
                coord_str = str(coord)
            except Exception:
                coord_str = ""

        # Convert value to string
        if value is None:
            value_str = ""
        else:
            if isinstance(value, (list, tuple)):
                try:
                    value_str = sep.join(str(v) for v in value)
                except Exception:
                    value_str = ""
            else:
                try:
                    value_str = str(value)
                except Exception:
                    value_str = ""

        # Build the line
        if value_str:
            line = coord_str + sep + value_str
        else:
            line = coord_str
        lines.append(line)

    # Join all lines with newline characters
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the coordinate name
    if not isinstance(coord_name, str):
        raise TypeError(
            f"coord_name must be a string, got {type(coord_name).__name__}"
        )

    # Ensure the attribute exists
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute")

    err_indices = getattr(self, "_err_indices")
    if err_indices is None:
        raise ValueError("Error indices data is None")

    # Retrieve indices based on the expected structure of _err_indices
    if isinstance(err_indices, dict):
        if coord_name not in err_indices:
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices")
        indices = err_indices[coord_name]
    elif isinstance(err_indices, (list, tuple)):
        indices = None
        for item in err_indices:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                name, idx = item
                if name == coord_name:
                    indices = idx
                    break
        if indices is None:
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices")
    else:
        raise TypeError(
            f"_err_indices must be a dict or list/tuple, got {type(err_indices).__name__}"
        )

    # Ensure the indices are iterable and contain integers
    if not isinstance(indices, (list, tuple)):
        try:
            indices = list(indices)
        except TypeError:
            raise TypeError(
                f"Error indices for coordinate '{coord_name}' must be iterable"
            )

    if not all(isinstance(i, int) for i in indices):
        raise TypeError("All error indices must be integers")

    return indices

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert to list to allow iteration and length checks
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except Exception as exc:
        raise ValueError("bins and edges must be iterable") from exc

    # Basic validation
    if len(edges_list) < 2:
        raise ValueError("edges must contain at least two elements")
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError("bins length must be one less than edges length")

    # Compute widths of each bin
    widths = []
    for i in range(len(edges_list) - 1):
        try:
            width = edges_list[i + 1] - edges_list[i]
        except Exception as exc:
            raise ValueError(f"edges must support subtraction: {exc}") from exc
        if width < 0:
            raise ValueError("edges must be in non-decreasing order")
        widths.append(width)

    # Compute integral as sum of bin value times bin width
    total = 0.0
    for b, w in zip(bins_list, widths):
        try:
            total += float(b) * float(w)
        except Exception as exc:
            raise ValueError(f"bins must contain numeric values: {exc}") from exc

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If seq itself is a FillRequest instance, it's valid
        if isinstance(seq, FillRequest):
            return True
        # If seq is a Source instance, it's not a valid FillRequestSeq
        if isinstance(seq, Source):
            return False
        # Try to iterate over seq
        iterator = iter(seq)
    except Exception:
        # seq is not iterable or other error
        return False
    # Check if any element in the sequence is a FillRequest
    for item in iterator:
        if isinstance(item, FillRequest):
            return True
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    if obj is None:
        return False
    return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")

    def _diff(a, b, lvl):
        result = {}
        for key, val in a.items():
            if key not in b:
                result[key] = val
            else:
                val2 = b[key]
                if isinstance(val, dict) and isinstance(val2, dict):
                    if lvl == 0:
                        if val != val2:
                            result[key] = val
                    else:
                        # For infinite recursion (lvl < 0) keep lvl unchanged
                        sublvl = lvl - 1 if lvl > 0 else lvl
                        subdiff = _diff(val, val2, sublvl)
                        if subdiff:
                            result[key] = subdiff
                else:
                    if val != val2:
                        result[key] = val
        return result

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        # Convert weight to a float; raise if not numeric
        try:
            w = float(weight)
        except Exception:
            raise TypeError("weight must be a numeric value")

        # Ensure coord is an iterable of numbers
        if isinstance(coord, (int, float)):
            coord = [coord]
        else:
            try:
                coord = list(coord)
            except Exception:
                raise TypeError("coord must be a number or an iterable of numbers")

        # Check dimensionality matches the histogram
        if len(coord) != len(self._edges):
            # Mismatched dimension: ignore the fill request
            return

        # Find the bin indices for each coordinate dimension
        indices = []
        for dim, val in enumerate(coord):
            edges = self._edges[dim]
            # If the value is outside the bin edges, ignore the fill
            if val < edges[0] or val >= edges[-1]:
                return
            # Binary search to find the correct bin index
            lo, hi = 0, len(edges) - 1
            while lo < hi - 1:
                mid = (lo + hi) // 2
                if val < edges[mid]:
                    hi = mid
                else:
                    lo = mid
            indices.append(lo)

        # Increment the histogram bin by the weight
        self._data[tuple(indices)] += w
    except Exception as exc:
        # Re-raise the exception to signal an error condition
        raise exc

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource name to its default observer schema.
    """
    try:
        # Safely access the manifest list
        manifest = getattr(app, "spec", None)
        if manifest is None:
            return {}
        manifest = getattr(manifest, "manifest", None)
        if manifest is None or not isinstance(manifest, list):
            return {}

        # Custom observer schemas, if any
        custom_schemas = getattr(app.spec, "observer_schema", {})
        if not isinstance(custom_schemas, dict):
            custom_schemas = {}

        default_schema = {
            "metadata": {
                "name": {"type": "string"},
                "namespace": {"type": "string"},
            },
            "status": {"type": "object"},
        }

        result = {}
        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            metadata = resource.get("metadata", {})
            if not isinstance(metadata, dict):
                continue
            name = metadata.get("name")
            if not name:
                continue
            if name in custom_schemas:
                continue
            result[name] = default_schema.copy()
        return result
    except Exception:
        # In case of any unexpected error, return an empty mapping
        return {}

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve the path argument to a string filesystem path
        import os
        if path is None:
            return False

        # Handle pathlib.Path or similar objects
        if hasattr(path, 'as_posix'):
            path = path.as_posix()
        elif hasattr(path, 'path'):
            path = path.path
        elif hasattr(path, 'root'):
            path = path.root
        else:
            # If it's already a string or bytes, keep it; otherwise invalid
            if not isinstance(path, (str, bytes)):
                return False

        # Ensure we have a string path
        path = os.fspath(path) if hasattr(os, 'fspath') else str(path)

        # Path must exist and be a directory
        if not os.path.isdir(path):
            return False

        # Check for the mandatory .ocfl_version file
        ocfl_version_file = os.path.join(path, '.ocfl_version')
        if not os.path.isfile(ocfl_version_file):
            return False

        # Read and validate the version string
        try:
            with open(ocfl_version_file, 'r', encoding='utf-8') as f:
                version = f.read().strip()
        except Exception:
            return False

        if not version:
            return False

        # Optional: check for .ocfl_root file and warn if missing or empty
        ocfl_root_file = os.path.join(path, '.ocfl_root')
        import warnings
        if os.path.isfile(ocfl_root_file):
            try:
                with open(ocfl_root_file, 'r', encoding='utf-8') as f:
                    root = f.read().strip()
                if not root:
                    warnings.warn("Empty .ocfl_root file in OCFL object.")
            except Exception:
                warnings.warn("Cannot read .ocfl_root file in OCFL object.")
        else:
            warnings.warn("Missing .ocfl_root file in OCFL object.")

        # If all checks pass, consider the object valid
        return True
    except Exception:
        # Any unexpected error results in an invalid object
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Ensure prefix is a string
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        try:
            prefix = str(prefix)
        except Exception:
            prefix = ''
    try:
        # Determine basic status
        status = "OK" if getattr(self, 'is_valid', True) else "FAIL"
        parts = [prefix] if prefix else []
        parts.append(status)

        # Handle errors
        if hasattr(self, 'errors'):
            errors = getattr(self, 'errors')
            try:
                error_count = len(errors)
            except Exception:
                error_count = 1 if errors else 0
            if error_count:
                parts.append(f"Errors: {error_count}")

        # Handle warnings
        if hasattr(self, 'warnings'):
            warnings = getattr(self, 'warnings')
            try:
                warning_count = len(warnings)
            except Exception:
                warning_count = 1 if warnings else 0
            if warning_count:
                parts.append(f"Warnings: {warning_count}")

        return ' '.join(parts)
    except Exception as exc:
        # Fallback in case of unexpected errors
        return f"{prefix}Error generating status: {exc}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if prefix is None:
        prefix = ''
    # Attempt to retrieve the log attribute from common names
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, 'log', None)
    if log is None:
        log = getattr(self, '_log', None)
    if log is None:
        return ''
    # If the log is already a string, just prepend the prefix
    if isinstance(log, str):
        return prefix + log
    # If the log is a list or tuple, format each element
    if isinstance(log, (list, tuple)):
        return '\n'.join(prefix + str(item) for item in log)
    # If the log is a dictionary, format key: value pairs
    if isinstance(log, dict):
        return '\n'.join(prefix + f'{k}: {v}' for k, v in log.items())
    # If the log is an iterable but not a string, format each element
    try:
        iter(log)
    except TypeError:
        # Not iterable, just convert to string
        return prefix + str(log)
    # For other iterables, format each element
    return '\n'.join(prefix + str(item) for item in log)

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary.")

    # Determine spec version
    spec_version = getattr(self, "spec_version", None)

    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Try to parse a version from the type string
            if type_val == "inventory":
                spec_version = 1
            elif type_val.startswith("inventory_v"):
                try:
                    spec_version = int(type_val.split("_v")[-1])
                except ValueError:
                    pass
        # Fallback to the instance's spec_version if still None
        if spec_version is None:
            spec_version = getattr(self, "spec_version", 1)
    else:
        spec_version = getattr(self, "spec_version", 1)

    # Ensure spec_version is an integer
    try:
        spec_version = int(spec_version)
    except (TypeError, ValueError):
        raise ValueError(f"Invalid spec_version: {spec_version}")

    # Validation rules per spec version
    if spec_version == 1:
        required_keys = ["name", "items"]
        list_key = "items"
    elif spec_version == 2:
        required_keys = ["metadata", "entries"]
        list_key = "entries"
    else:
        raise ValueError(f"Unsupported spec version: {spec_version}")

    missing_keys = [k for k in required_keys if k not in inventory]
    if missing_keys:
        raise ValueError(
            f"Missing required keys for spec version {spec_version}: {missing_keys}"
        )

    # Ensure the list key is actually a list
    if not isinstance(inventory.get(list_key), list):
        raise ValueError(f"'{list_key}' must be a list in spec version {spec_version}.")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    try:
        digests_used_set = set(digests_used)
    except TypeError:
        raise TypeError("digests_used must be an iterable of digests")

    # Extract the set of digests present in the manifest
    manifest_digests = set(manifest_files.values())

    # Check that every digest that is used is present in the manifest
    missing_in_manifest = digests_used_set - manifest_digests
    if missing_in_manifest:
        raise ValueError(
            f"Digests used but not present in manifest: {sorted(missing_in_manifest)}"
        )

    # Check that every digest present in the manifest is actually used
    unused_in_manifest = manifest_digests - digests_used_set
    if unused_in_manifest:
        raise ValueError(
            f"Digests present in manifest but not used: {sorted(unused_in_manifest)}"
        )

    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if prior is None:
        raise TypeError("prior must be an InventoryValidator instance, got None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Required attributes that must exist on both objects
    required_attrs = ("inventory_version", "inventory_id", "inventory_date")
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"self object missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"prior object missing required attribute '{attr}'")

    # Retrieve values
    self_version = getattr(self, "inventory_version")
    prior_version = getattr(prior, "inventory_version")
    self_id = getattr(self, "inventory_id")
    prior_id = getattr(prior, "inventory_id")
    self_date = getattr(self, "inventory_date")
    prior_date = getattr(prior, "inventory_date")

    # Ensure versions are comparable and prior is older
    try:
        if prior_version >= self_version:
            raise ValueError(
                "prior inventory_version must be less than current inventory_version"
            )
    except TypeError:
        raise TypeError(
            "inventory_version values must be comparable (e.g., int, float, or str)"
        )

    # Ensure IDs differ
    if prior_id == self_id:
        raise ValueError("prior inventory_id must differ from current inventory_id")

    # Ensure dates are comparable and prior is earlier
    try:
        if prior_date >= self_date:
            raise ValueError(
                "prior inventory_date must be earlier than current inventory_date"
            )
    except TypeError:
        raise TypeError(
            "inventory_date values must be comparable (e.g., datetime or ISO string)"
        )

    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if inventory is None or not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version is None:
        raise ValueError("version must be specified")

    # Helper to normalize a file entry to a string
    def _to_str(val):
        if isinstance(val, (list, tuple)):
            # If multiple files are listed, return the first one
            return str(val[0]) if val else ""
        return str(val)

    # Determine if inventory is a list of versions or a single mapping
    if "versions" in inventory and isinstance(inventory["versions"], list):
        versions = inventory["versions"]
        # Find the index of the requested version
        ver_index = None
        if isinstance(version, int):
            if 0 <= version < len(versions):
                ver_index = version
        else:
            # Try to match by 'name' or 'id'
            for idx, v in enumerate(versions):
                if isinstance(v, dict) and (v.get("name") == version or v.get("id") == version):
                    ver_index = idx
                    break
        if ver_index is None:
            raise ValueError(f"Version {version!r} not found in inventory")
        # Build the result mapping
        result = {}
        # Get the files mapping for the target version
        target_files = versions[ver_index].get("files", {})
        if not isinstance(target_files, dict):
            raise ValueError("Expected 'files' to be a dict in the target version")
        # For each logical path in the target version
        for logical_path, content_file in target_files.items():
            content_set = set()
            # Add the content file from the target version
            content_set.add(_to_str(content_file))
            # Check later versions for duplicates
            for later in versions[ver_index + 1 :]:
                later_files = later.get("files", {})
                if not isinstance(later_files, dict):
                    continue
                if logical_path in later_files:
                    content_set.add(_to_str(later_files[logical_path]))
            result[logical_path] = content_set
        return result

    # If inventory is a direct mapping of logical_path -> content_file
    if "files" in inventory and isinstance(inventory["files"], dict):
        files_map = inventory["files"]
        result = {}
        for logical_path, content_file in files_map.items():
            result[logical_path] = {_to_str(content_file)}
        return result

    # If inventory itself is a mapping of logical_path -> content_file
    if isinstance(inventory, dict):
        result = {}
        for logical_path, content_file in inventory.items():
            result[logical_path] = {_to_str(content_file)}
        return result

    raise TypeError("Unsupported inventory format")

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Validate input type
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"path must be a string or bytes, got {type(path).__name__}")
    # Convert bytes to str if necessary
    if isinstance(path, bytes):
        try:
            path = path.decode()
        except Exception as e:
            raise ValueError(f"Unable to decode bytes path: {e}") from e
    # If path does not exist or is not a directory, return empty list
    try:
        if not os.path.isdir(path):
            return []
        # List directory contents
        entries = os.listdir(path)
    except OSError:
        # Any OS-related error (e.g., permission denied) results in empty list
        return []
    # Filter only files (including symlinks to files)
    files = []
    for entry in entries:
        full_path = os.path.join(path, entry)
        try:
            if os.path.isfile(full_path):
                files.append(entry)
        except OSError:
            # Skip entries that cause errors (e.g., broken symlinks)
            continue
    return files

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise TypeError("folder must be a string")
    import os
    if not os.path.isdir(folder):
        raise ValueError(f"Folder {folder!r} does not exist or is not a directory")
    try:
        entries = os.listdir(folder)
    except OSError as exc:
        raise ValueError(f"Unable to list directory {folder!r}: {exc}") from exc
    xml_basenames = set()
    for entry in entries:
        full_path = os.path.join(folder, entry)
        if os.path.isfile(full_path):
            _, ext = os.path.splitext(entry)
            if ext.lower() == ".xml":
                basename = os.path.splitext(entry)[0]
                xml_basenames.add(basename)
    result = {}
    for basename in xml_basenames:
        group = []
        for entry in entries:
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                name_no_ext = os.path.splitext(entry)[0]
                if name_no_ext == basename:
                    group.append(full_path)
        if group:
            result[basename] = sorted(group)
    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    Se nenhum match for encontrado, retorna None.
    """
    if node is None or not isinstance(pubdate_xpaths, (list, tuple)):
        return None

    for xpath in pubdate_xpaths:
        if not isinstance(xpath, str):
            continue
        try:
            matches = node.xpath(xpath)
        except Exception:
            continue
        if not matches:
            continue
        first = matches[0]
        # If the match is a string, return it directly
        if isinstance(first, str):
            return first
        # If it's an lxml element, try to get its text content
        if hasattr(first, "text"):
            return first.text
        if hasattr(first, "text_content"):
            return first.text_content()
        # Fallback to string representation
        try:
            return str(first)
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    if not isinstance(indent, int):
        raise TypeError("indent must be an integer")
    if indent < 0:
        indent = 0
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    visited = set()

    def _pretty(obj, level):
        # Detect recursion
        obj_id = id(obj)
        if obj_id in visited:
            return f"<Recursion on {type(obj).__name__} with id={obj_id}>"
        visited.add(obj_id)

        # Basic types
        if isinstance(obj, (str, int, float, bool, type(None))):
            rep = repr(obj)
            if debug:
                rep = f"{type(obj).__name__}: {rep}"
            return rep

        # Containers
        if isinstance(obj, dict):
            lines = []
            prefix = f"dict {" if debug else "{"
            lines.append(prefix)
            for k, v in obj.items():
                key_str = _pretty(k, level + 1)
                val_str = _pretty(v, level + 1)
                lines.append(' ' * indent * (level + 1) + f"{key_str}: {val_str},")
            lines.append(' ' * indent * level + "}")
            return "\n".join(lines)

        if isinstance(obj, list):
            lines = []
            prefix = f"list [" if debug else "["
            lines.append(prefix)
            for item in obj:
                item_str = _pretty(item, level + 1)
                lines.append(' ' * indent * (level + 1) + f"{item_str},")
            lines.append(' ' * indent * level + "]")
            return "\n".join(lines)

        if isinstance(obj, tuple):
            lines = []
            prefix = f"tuple (" if debug else "("
            lines.append(prefix)
            for item in obj:
                item_str = _pretty(item, level + 1)
                lines.append(' ' * indent * (level + 1) + f"{item_str},")
            lines.append(' ' * indent * level + ")")
            return "\n".join(lines)

        if isinstance(obj, set):
            lines = []
            prefix = f"set {" if debug else "{"
            lines.append(prefix)
            for item in obj:
                item_str = _pretty(item, level + 1)
                lines.append(' ' * indent * (level + 1) + f"{item_str},")
            lines.append(' ' * indent * level + "}")
            return "\n".join(lines)

        # Custom objects with __dict__
        if hasattr(obj, "__dict__"):
            lines = []
            lines.append(f"{type(obj).__name__}(")
            for key in sorted(obj.__dict__):
                val = getattr(obj, key)
                val_str = _pretty(val, level + 1)
                lines.append(' ' * indent * (level + 1) + f"{key}={val_str},")
            lines.append(' ' * indent * level + ")")
            return "\n".join(lines)

        # Custom objects with __slots__
        if hasattr(obj, "__slots__"):
            lines = []
            lines.append(f"{type(obj).__name__}(")
            for slot in obj.__slots__:
                try:
                    val = getattr(obj, slot)
                except AttributeError:
                    val = None
                val_str = _pretty(val, level + 1)
                lines.append(' ' * indent * (level + 1) + f"{slot}={val_str},")
            lines.append(' ' * indent * level + ")")
            return "\n".join(lines)

        # Fallback
        try:
            rep = repr(obj)
        except Exception:
            rep = str(obj)
        if debug:
            rep = f"{type(obj).__name__}: {rep}"
        return rep

    try:
        return _pretty(self, 0)
    except RecursionError:
        return f"<RecursionError on {type(self).__name__}>"
    except Exception:
        # In case pretty fails, return a simple representation
        try:
            return repr(self)
        except Exception:
            return str(self)

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Attempt to read a VERSION file in the current directory
        with open("VERSION", "r", encoding="utf-8") as f:
            version = f.read().strip()
        if not version:
            raise ValueError("VERSION file is empty")
        # Return a minimal version dictionary
        return {
            "version": version,
            "full-revisionid": None,
            "dirty": False,
            "error": None,
        }
    except Exception as exc:
        # Fallback to a default version if anything goes wrong
        return {
            "version": "0.0.0",
            "full-revisionid": None,
            "dirty": False,
            "error": str(exc),
        }

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        return '.' if '+' in str(pieces) else '+'
    except Exception:
        return '+'

def initialize(self):
        """Create and initialize a new OCFL storage root."""
        # Ensure the root path attribute exists and is a string
        if not hasattr(self, "root_path"):
            raise AttributeError("Missing 'root_path' attribute on the instance.")
        root_path = self.root_path
        if not isinstance(root_path, str):
            raise TypeError(f"root_path must be a string, got {type(root_path).__name__}")

        # Resolve to an absolute path
        root_path = os.path.abspath(root_path)

        try:
            # If the path exists, validate it
            if os.path.exists(root_path):
                if os.path.isfile(root_path):
                    raise ValueError(f"Root path '{root_path}' exists and is a file.")
                # Directory exists: check if already initialized
                ocfl_root_file = os.path.join(root_path, ".ocfl_root")
                if os.path.exists(ocfl_root_file):
                    raise ValueError(f"OCFL root already initialized at '{root_path}'.")
            else:
                # Create the root directory
                os.makedirs(root_path, exist_ok=True)

            # Create the objects directory
            objects_dir = os.path.join(root_path, "objects")
            os.makedirs(objects_dir, exist_ok=True)

            # Write the .ocfl_root file with minimal metadata
            ocfl_root_file = os.path.join(root_path, ".ocfl_root")
            ocfl_metadata = {
                "ocflVersion": "1.0",
                "layout": "hash-2",
                "layoutVersion": "1.0"
            }
            with open(ocfl_root_file, "w", encoding="utf-8") as f:
                json.dump(ocfl_metadata, f, indent=2)

            return True
        except OSError as e:
            raise RuntimeError(f"Failed to initialize OCFL root at '{root_path}': {e}") from e
        except Exception as e:
            raise RuntimeError(f"Unexpected error during OCFL root initialization: {e}") from e

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Validate input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return {}

    # Load root inventory if not already loaded
    if not hasattr(self, "root_inventory") or self.root_inventory is None:
        if not hasattr(self, "root_inventory_path"):
            raise AttributeError("root_inventory_path attribute is missing")
        try:
            with open(self.root_inventory_path, "r", encoding="utf-8") as f:
                self.root_inventory = json.load(f)
        except Exception as exc:
            raise RuntimeError(f"Failed to load root inventory: {exc}") from exc

    root_inv = self.root_inventory
    differences = {}

    for ver_dir in version_dirs:
        if not isinstance(ver_dir, str):
            raise TypeError(f"Version directory name must be a string, got {type(ver_dir)}")
        if not os.path.isdir(ver_dir):
            raise FileNotFoundError(f"Version directory '{ver_dir}' does not exist")

        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing in version directory '{ver_dir}'")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                ver_inv = json.load(f)
        except Exception as exc:
            raise RuntimeError(f"Failed to load inventory for '{ver_dir}': {exc}") from exc

        # Compare digests
        diff_items = []
        for item, digest in ver_inv.items():
            root_digest = root_inv.get(item)
            if root_digest is None or digest != root_digest:
                diff_items.append(item)

        if diff_items:
            differences[ver_dir] = diff_items

    # Store differences for later validation
    self.different_digests = differences
    return differences

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        # Validate params
        if not isinstance(params, dict):
            raise TypeError("params must be a dict")

        # If bug_ids is None or empty, return params unchanged
        if bug_ids is None:
            return params

        # Convert bug_ids to a list of values
        if isinstance(bug_ids, (list, tuple, set)):
            bug_id_list = list(bug_ids)
        elif isinstance(bug_ids, str):
            # Split comma-separated string and strip whitespace
            bug_id_list = [x.strip() for x in bug_ids.split(',') if x.strip()]
        else:
            # Assume a single id
            bug_id_list = [bug_ids]

        # If after conversion the list is empty, return params unchanged
        if not bug_id_list:
            return params

        # Convert each id to string, skipping invalid types
        bug_id_strs = []
        for bid in bug_id_list:
            if isinstance(bid, (int, float)):
                # Convert numeric types to string (int for consistency)
                bug_id_strs.append(str(int(bid)))
            elif isinstance(bid, str):
                bid_str = bid.strip()
                if bid_str:
                    bug_id_strs.append(bid_str)
            else:
                # Skip unsupported types
                continue

        if not bug_id_strs:
            return params

        # Remove duplicates while preserving order
        seen = set()
        unique_bug_ids = []
        for bid in bug_id_strs:
            if bid not in seen:
                seen.add(bid)
                unique_bug_ids.append(bid)

        # Join IDs into a comma-separated string
        ids_str = ','.join(unique_bug_ids)

        # Amend the params dictionary
        params['ids'] = ids_str

        return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode (by duck typing)
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list) and all(
            isinstance(v, tuple) and len(v) == 2 for v in node.value
        )

    # Recursive merge of two mapping nodes
    def merge_mapping_nodes(node_a, node_b):
        # Use the tag from the first node
        tag = getattr(node_a, 'tag', None)
        # Build a dict of subkey -> (key_node, value_node)
        merged = {}
        # Helper to process a mapping node's entries
        def process_entries(node):
            for k_node, v_node in node.value:
                key = getattr(k_node, 'value', None)
                if key is None:
                    continue
                if key in merged:
                    # Merge existing
                    existing_k, existing_v = merged[key]
                    if is_mapping_node(existing_v) and is_mapping_node(v_node):
                        merged[key] = (existing_k, merge_mapping_nodes(existing_v, v_node))
                    else:
                        # Last wins
                        merged[key] = (existing_k, v_node)
                else:
                    merged[key] = (k_node, v_node)
        process_entries(node_a)
        process_entries(node_b)
        # Reconstruct the mapping node
        new_value = [(k, v) for _, (k, v) in merged.items()]
        # Create a new node instance if possible; otherwise, modify node_a
        try:
            # Attempt to create a new instance of the same class
            new_node = node_a.__class__(tag=tag, value=new_value)
        except Exception:
            # Fallback: modify node_a in place
            node_a.tag = tag
            node_a.value = new_value
            new_node = node_a
        return new_node

    from collections import OrderedDict
    merged_dict = OrderedDict()
    for key_node, value_node in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            continue
        if key not in merged_dict:
            merged_dict[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = merged_dict[key]
            if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                merged_value = merge_mapping_nodes(existing_value_node, value_node)
                merged_dict[key] = (existing_key_node, merged_value)
            else:
                # Last wins
                merged_dict[key] = (existing_key_node, value_node)
    return [(k_node, v_node) for k_node, v_node in merged_dict.values()]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise TypeError('parser cannot be None')
    # Ensure the object behaves like an ArgumentParser by checking for the _actions attribute
    if not hasattr(parser, '_actions'):
        raise TypeError('Expected an argparse.ArgumentParser instance')
    flags = []
    for action in parser._actions:
        option_strings = getattr(action, 'option_strings', None)
        if isinstance(option_strings, (list, tuple)):
            for opt in option_strings:
                if isinstance(opt, str):
                    flags.append(opt)
                else:
                    # Fallback: convert non-string option strings to string
                    flags.append(str(opt))
    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if unparsed_arguments is None:
        unparsed_arguments = []
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")

    parsed_namespaces = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        if parser is None:
            raise TypeError(f"Parser for subparser '{name}' is None")
        if not hasattr(parser, 'parse_known_args') or not callable(parser.parse_known_args):
            raise TypeError(f"Parser for subparser '{name}' does not have a callable parse_known_args method")
        try:
            ns, unknown = parser.parse_known_args(list(unparsed_arguments))
        except SystemExit as e:
            # argparse uses SystemExit on error; convert to ValueError for clarity
            raise ValueError(f"Argument parsing failed for subparser '{name}': {e}") from e
        parsed_namespaces[name] = ns
        unknown_sets.append(set(unknown))

    # Determine remaining arguments: those that are not recognized by any subparser
    if unknown_sets:
        # Intersection of all unknown sets gives arguments not claimed by any subparser
        remaining_set = set.intersection(*unknown_sets)
    else:
        # No subparsers: all arguments remain
        remaining_set = set(unparsed_arguments)

    remaining_args = [arg for arg in unparsed_arguments if arg in remaining_set]

    return parsed_namespaces

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode (by duck typing)
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list) and all(
            isinstance(v, tuple) for v in node.value
        )

    # Merge two nodes: if both are mapping nodes, merge recursively; otherwise, return the second
    def merge_nodes(a, b):
        if is_mapping_node(a) and is_mapping_node(b):
            return merge_mapping_nodes(a, b)
        # For non-mapping nodes, the last value wins
        return b

    # Merge two mapping nodes
    def merge_mapping_nodes(a, b):
        # Build a dict of key -> (key_node, value_node) from a
        merged_dict = {}
        order = []
        for key_node, val_node in a.value:
            key = key_node.value
            if key not in merged_dict:
                merged_dict[key] = (key_node, val_node)
                order.append(key)
            else:
                # Duplicate key within the same mapping; merge values
                _, existing_val = merged_dict[key]
                merged_dict[key] = (key_node, merge_nodes(existing_val, val_node))
        # Merge entries from b
        for key_node, val_node in b.value:
            key = key_node.value
            if key not in merged_dict:
                merged_dict[key] = (key_node, val_node)
                order.append(key)
            else:
                _, existing_val = merged_dict[key]
                merged_dict[key] = (merged_dict[key][0], merge_nodes(existing_val, val_node))
        # Reconstruct the mapping node
        merged_entries = [(merged_dict[k][0], merged_dict[k][1]) for k in order]
        # Preserve the tag from the first mapping node (a)
        tag = getattr(a, 'tag', None)
        # Create a new instance of the same class as a
        MappingNodeCls = type(a)
        return MappingNodeCls(tag, merged_entries)

    # Main merging logic for the top-level list of nodes
    merged_dict = {}
    order = []
    for key_node, val_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = (key_node, val_node)
            order.append(key)
        else:
            _, existing_val = merged_dict[key]
            merged_dict[key] = (merged_dict[key][0], merge_nodes(existing_val, val_node))
    # Build the result list preserving order
    result = [(merged_dict[k][0], merged_dict[k][1]) for k in order]
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        import argparse
    except Exception:
        raise RuntimeError("argparse module is required for parser_flags")

    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    try:
        for action in parser._actions:
            # action.option_strings may be a list of flag strings
            try:
                option_strings = action.option_strings
            except AttributeError:
                continue
            if not option_strings:
                continue
            for opt in option_strings:
                if isinstance(opt, str):
                    flags.append(opt)
    except Exception as e:
        raise RuntimeError(f"Error processing parser actions: {e}")

    return " ".join(flags) if flags else ""

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Validate input types
    if not isinstance(url, str):
        return url
    if not isinstance(url_args, dict):
        url_args = {}

    import re

    # Pattern to find placeholders like {key}
    pattern = re.compile(r'\{([^{}]+)\}')

    def _replacer(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            # Convert None to empty string, otherwise to string
            return '' if value is None else str(value)
        # If key not found, leave placeholder unchanged
        return match.group(0)

    return pattern.sub(_replacer, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Only strings can represent a None value in textual form
    if not isinstance(val, str):
        return False
    # Normalize the string: strip whitespace and convert to lowercase
    normalized = val.strip().lower()
    # Common textual representations of None
    return normalized in {"none", "null", "nil"}

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        import argparse
    except Exception as exc:
        raise RuntimeError("argparse module is required") from exc

    if parser is None:
        raise TypeError("parser cannot be None")
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    # Use getattr to avoid AttributeError if _actions is missing
    for action in getattr(parser, "_actions", []):
        # Some actions may not have option_strings attribute
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            # Ensure we only add strings
            for opt in option_strings:
                if isinstance(opt, str):
                    flags.append(opt)
    return " ".join(flags)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    try:
        stack = list(cls.__subclasses__())
    except Exception as e:
        raise RuntimeError(f"Failed to retrieve subclasses of {cls}: {e}") from e
    while stack:
        sub = stack.pop()
        if sub not in result:
            result.add(sub)
            try:
                stack.extend(sub.__subclasses__())
            except Exception:
                # Skip subclasses that cannot be retrieved
                continue
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate types
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if any(not isinstance(ch, str) for ch in alphabet):
        raise TypeError("All elements of alphabet must be str")

    # Validate alphabet
    if not alphabet:
        raise ValueError("alphabet must contain at least one symbol")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate symbols")

    base = len(alphabet)
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    # Empty string maps to 0
    if string == "":
        return 0

    # Validate string characters
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' not found in alphabet")

    # Convert
    result = 0
    for ch in string:
        result = result * base + char_to_value[ch]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems including macOS
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # os.uname() not available (e.g., on Windows). Fall back to platform module.
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            # If any error occurs, assume not macOS
            return False
    except Exception:
        # Any other unexpected error: assume not macOS
        return False

def unquote(name):
    """Remove quote from the given name."""
    if name is None:
        return None
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    try:
        # Remove leading and trailing single or double quotes, including multiple
        return re.sub(r"^['\"]+|['\"]+$", "", name)
    except Exception as exc:
        raise ValueError(f"Failed to unquote name: {exc}") from exc

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Validate inputs
    if not isinstance(archive_path, str):
        raise TypeError("archive_path must be a string")
    if filename is not None and not isinstance(filename, str):
        raise TypeError("filename must be a string or None")
    # Convert tmp_path to string
    try:
        tmp_path_str = str(tmp_path)
    except Exception as exc:
        raise TypeError("tmp_path must be convertible to string") from exc

    # Determine extraction directory name
    if filename:
        dir_name = filename
    else:
        # Strip common archive extensions
        base = archive_path.split("/")[-1]
        for ext in (".tar.gz", ".tgz", ".tar", ".zip"):
            if base.lower().endswith(ext):
                base = base[: -len(ext)]
                break
        dir_name = base

    # Full extraction path
    dest_dir = tmp_path_str.rstrip("/") + "/" + dir_name

    # Create destination directory
    try:
        subprocess.run(
            ["mkdir", "-p", dest_dir],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Failed to create directory '{dest_dir}': {exc.stderr.decode().strip()}") from exc

    # Determine extraction command based on archive type
    lower_path = archive_path.lower()
    if lower_path.endswith((".tar.gz", ".tgz", ".tar")):
        cmd = ["tar", "-xf", archive_path, "-C", dest_dir]
    elif lower_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", dest_dir]
    else:
        raise ValueError(f"Unsupported archive format for '{archive_path}'")

    # Run extraction
    try:
        subprocess.run(
            cmd,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Extraction failed: {exc.stderr.decode().strip()}") from exc

    # Return file URL
    return f"file://{dest_dir}"

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str):
            return False
        if not filename:
            return False
        _, ext = os.path.splitext(filename)
        if not ext:
            return False
        return ext.lower() in {'.txt', '.md', '.csv', '.json'}
    except Exception:
        return False

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or the special "always" keyword
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        raise ValueError("Frequency string is empty")
    if freq.lower() == "always":
        return None

    # Expect exactly two parts: a number and a unit
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: {frequency!r}")

    num_str, unit = parts
    try:
        num = int(num_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {num_str!r}")

    unit = unit.lower()
    # Normalize plural forms by stripping a trailing 's'
    singular = unit.rstrip('s')
    unit_map = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
        'millisecond': 'milliseconds',
        'microsecond': 'microseconds',
    }

    if singular not in unit_map:
        raise ValueError(f"Unknown time unit: {unit!r}")

    kwargs = {unit_map[singular]: num}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Direct string checks for common localhost identifiers
    if host.lower() == "localhost":
        return True

    # Attempt to resolve the host to IP addresses
    try:
        addr_info = socket.getaddrinfo(host, None)
    except (socket.gaierror, ValueError):
        return False

    # Inspect each resolved address
    for info in addr_info:
        family, _, _, _, sockaddr = info
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == "::1":
                return True

    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise TypeError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # If file exists and we are not allowed to overwrite, abort
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")

    # Ensure the directory exists
    dir_path = os.path.dirname(config_filename)
    if dir_path:
        try:
            os.makedirs(dir_path, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories for '{config_filename}': {exc}") from exc

    # Write the configuration file
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        # Set the file mode
        os.chmod(config_filename, mode)
    except OSError as exc:
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Validate matcher type
    if not isinstance(matcher, (tuple, list)):
        raise TypeError("matcher must be a tuple or list containing the variable name and optional default value")
    if len(matcher) == 0:
        raise ValueError("matcher must contain at least the variable name")
    if len(matcher) > 2:
        raise ValueError("matcher must contain at most two elements: name and optional default")

    # Extract name and optional default
    name = matcher[0]
    if not isinstance(name, str):
        raise TypeError("variable name must be a string")
    default = matcher[1] if len(matcher) == 2 else None

    # Retrieve from environment
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    It escapes all regex metacharacters in the input string.
    If strip is True, leading and trailing whitespace is removed before escaping.
    """
    # Validate input types
    if not isinstance(pattern, str):
        raise TypeError(f"pattern must be a string, got {type(pattern).__name__}")
    if not isinstance(strip, bool):
        raise TypeError(f"strip must be a boolean, got {type(strip).__name__}")

    # Optionally strip whitespace
    if strip:
        pattern = pattern.strip()

    # Escape regex metacharacters
    try:
        escaped = re.escape(pattern)
    except Exception as e:
        raise ValueError(f"Failed to escape pattern: {e}") from e

    return escaped

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate commands
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, list):
        if not commands:
            raise ValueError("commands list cannot be empty")
        if not all(isinstance(c, str) for c in commands):
            raise TypeError("All elements of commands list must be strings")
        cmd_list = commands
    else:
        raise TypeError("commands must be a string or list of strings")

    # Validate args
    if args is None:
        args = []
    if not isinstance(args, list):
        raise TypeError("args must be a list")
    if not all(isinstance(a, str) for a in args):
        raise TypeError("All elements of args must be strings")

    # Combine command and arguments
    full_cmd = cmd_list + args

    # Validate cwd
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")

    # Validate env
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Verbose output
    if verbose:
        print("Running command:", " ".join(full_cmd))
        if cwd:
            print("Working directory:", cwd)
        if env:
            print("Environment variables:", env)

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command: {' '.join(full_cmd)}") from e

    if result.returncode != 0:
        err_msg = f"Command '{' '.join(full_cmd)}' exited with return code {result.returncode}"
        if not hide_stderr and result.stderr:
            err_msg += f"\nStderr: {result.stderr}"
        raise RuntimeError(err_msg)

    if verbose:
        if result.stdout:
            print("Stdout:")
            print(result.stdout)
        if not hide_stderr and result.stderr:
            print("Stderr:")
            print(result.stderr)

    return result.stdout

def is_ipv4(target):
    """Test if IPv4 address or not

    Returns:
        bool: True if target is a valid IPv4 address, False otherwise.
    """
    # Handle None or non-string inputs gracefully
    if target is None:
        return False
    # If it's already an IPv4Address instance, it's valid
    if isinstance(target, ipaddress.IPv4Address):
        return True
    # If it's an IPv6Address instance, it's not IPv4
    if isinstance(target, ipaddress.IPv6Address):
        return False
    try:
        # Attempt to create an IPv4Address; this will raise ValueError if invalid
        ipaddress.IPv4Address(target)
        return True
    except (ValueError, TypeError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            return yaml.safe_dump(obj, default_flow_style=False, allow_unicode=True)
        else:
            return yaml.dump(obj, Dumper=dumper, default_flow_style=False, allow_unicode=True)
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping YAML: {exc}") from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import logging
    import re

    # Attempt to import yaml if available
    try:
        import yaml
    except Exception:
        yaml = None

    config_map = {}
    error_records = []

    # Helper to create a LogRecord for an error
    def _log_error(msg, exc=None):
        record = logging.LogRecord(
            name='load_configurations',
            level=logging.ERROR,
            pathname=__file__ if '__file__' in globals() else '',
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc
        )
        error_records.append(record)

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)')

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1) or match.group(2)
                return os.getenv(var, '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env_in_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env_in_value(v) for v in value]
        else:
            return value

    # Helper to apply overrides (simple top‑level merge)
    def _apply_overrides(cfg, overrides_dict):
        if not isinstance(overrides_dict, dict):
            return cfg
        merged = dict(cfg) if isinstance(cfg, dict) else {}
        for k, v in overrides_dict.items():
            merged[k] = v
        return merged

    # Validate input
    if config_filenames is None:
        return {}, []

    for filename in config_filenames:
        if not isinstance(filename, str):
            _log_error(f"Configuration filename must be a string, got {type(filename).__name__}")
            continue
        if not os.path.isfile(filename):
            _log_error(f"Configuration file not found: {filename}")
            continue
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as e:
            _log_error(f"Error reading configuration file {filename}", exc_info=e)
            continue

        # Determine parser based on file extension
        ext = os.path.splitext(filename)[1].lower()
        parsed = None
        try:
            if ext in {'.json'}:
                parsed = json.loads(content)
            elif ext in {'.yaml', '.yml'} and yaml is not None:
                parsed = yaml.safe_load(content)
            else:
                # Try JSON first, then YAML if available
                try:
                    parsed = json.loads(content)
                except Exception:
                    if yaml is not None:
                        parsed = yaml.safe_load(content)
                    else:
                        raise ValueError(f"Unsupported file extension {ext} and no YAML parser available")
        except Exception as e:
            _log_error(f"Error parsing configuration file {filename}", exc_info=e)
            continue

        if parsed is None:
            _log_error(f"Parsed configuration is None for file {filename}")
            continue

        # Apply overrides if provided
        if overrides is not None:
            parsed = _apply_overrides(parsed, overrides)

        # Resolve environment variables if requested
        if resolve_env:
            try:
                parsed = _resolve_env_in_value(parsed)
            except Exception as e:
                _log_error(f"Error resolving environment variables in {filename}", exc_info=e)
                continue

        config_map[filename] = parsed

    return config_map, error_records

def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Ensure the class has a mapping of handlers
        if not hasattr(cls, "_protocol_handlers"):
            raise AttributeError(
                f"{cls.__name__} does not define a '_protocol_handlers' attribute"
            )

        handlers = cls._protocol_handlers

        # Validate protocol_version type
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )

        # If no specific version requested, return a copy of all handlers
        if protocol_version is None:
            return dict(handlers)

        # Return only the requested version if it exists
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is an iterable of strings, not a single string or bytes
    if values is None:
        raise TypeError("values must not be None")
    if isinstance(values, (str, bytes, bytearray)):
        raise TypeError("values must be an iterable of strings, not a single string or bytes")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")
    raw_values = []
    for v in iterator:
        if not isinstance(v, str):
            raise TypeError(f"All elements of values must be str, got {type(v).__name__}")
        raw_values.append(v)
    try:
        return cls(raw_values)
    except Exception as exc:
        raise RuntimeError(f"Failed to create Bookmarks from raw values: {exc}") from exc

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Basic validation
    if hist is None:
        raise ValueError("hist must not be None")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
    if not isinstance(field_names, (tuple, list)):
        raise TypeError("field_names must be a tuple or list")
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be callable or None")

    # Determine scale
    if scale is True:
        # Try to get scale from histogram
        scale = getattr(hist, "scale", None)
    # else keep provided scale (could be None)

    # Prepare list of points
    points = []

    # Helper to get coordinate from a bin
    def _coord(bin_obj):
        if get_coordinate == "left":
            return getattr(bin_obj, "left", getattr(bin_obj, "edge_left", None))
        if get_coordinate == "right":
            return getattr(bin_obj, "right", getattr(bin_obj, "edge_right", None))
        # middle
        return getattr(bin_obj, "center", getattr(bin_obj, "mid", None))

    # Helper to get bin content
    def _content(bin_obj):
        # If bin_obj is numeric, return it
        if isinstance(bin_obj, (int, float)):
            return bin_obj
        # Try common attributes
        for attr in ("content", "value", "data"):
            if hasattr(bin_obj, attr):
                return getattr(bin_obj, attr)
        # Fallback: try to index if it's a sequence
        try:
            return bin_obj[0]
        except Exception:
            pass
        raise ValueError("Cannot determine bin content")

    # Iterate over bins
    for bin_obj in hist:
        try:
            coord = _coord(bin_obj)
            if coord is None:
                raise ValueError("Coordinate not found in bin")
        except Exception as e:
            raise ValueError(f"Error retrieving coordinate from bin: {e}")

        try:
            bin_val = _content(bin_obj)
        except Exception as e:
            raise ValueError(f"Error retrieving content from bin: {e}")

        # Apply make_value if provided
        if make_value is None:
            val = bin_val
        else:
            try:
                val = make_value(bin_val)
            except Exception as e:
                raise ValueError(f"make_value raised an exception: {e}")

        # Ensure val is iterable for multi-dimensional graph
        if isinstance(val, (tuple, list)):
            val_tuple = tuple(val)
        else:
            val_tuple = (val,)

        # On first point, validate field_names length
        if not points:
            if len(field_names) != len(val_tuple) + 1:  # +1 for coordinate
                raise ValueError(
                    f"field_names length {len(field_names)} does not match "
                    f"graph dimension {len(val_tuple)+1}"
                )

        point = (coord,) + val_tuple
        points.append(point)

    # Create a simple graph representation
    # Using a namedtuple for clarity
    from collections import namedtuple
    Graph = namedtuple("Graph", ["points", "field_names", "scale"])
    return Graph(points=points, field_names=tuple(field_names), scale=scale)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the cache has the expected attributes
    if not hasattr(self, "freq_to_keys") or not self.freq_to_keys:
        raise KeyError("Cache is empty")

    # Find the minimum frequency bucket
    try:
        min_freq = min(self.freq_to_keys.keys())
    except Exception as exc:
        raise KeyError("Cache is empty") from exc

    freq_dict = self.freq_to_keys[min_freq]

    # Pop a key from the frequency bucket
    try:
        if hasattr(freq_dict, "popitem"):
            # OrderedDict: pop the oldest key
            key, _ = freq_dict.popitem(last=False)
        else:
            # Regular dict: pop an arbitrary key
            key, _ = freq_dict.popitem()
    except Exception as exc:
        raise RuntimeError("Failed to pop key from frequency bucket") from exc

    # Retrieve and remove the value associated with the key
    if hasattr(self, "key_to_val"):
        if key not in self.key_to_val:
            raise KeyError(f"Key {key!r} not found in cache")
        value = self.key_to_val.pop(key)
    else:
        value = None

    # Remove the key's frequency record
    if hasattr(self, "key_to_freq"):
        self.key_to_freq.pop(key, None)

    # Clean up the frequency bucket if it became empty
    if not freq_dict:
        del self.freq_to_keys[min_freq]

    # Update the minimum frequency if necessary
    if hasattr(self, "min_freq"):
        if self.freq_to_keys:
            self.min_freq = min(self.freq_to_keys.keys())
        else:
            self.min_freq = 0

    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # The LRU cache is expected to store its items in an OrderedDict
    # named `_data`.  If that attribute is missing or not an OrderedDict,
    # we fall back to a list of keys (`_order`) that tracks usage order.
    # In all cases, the least‑recently used item is the first one in the
    # order list or the first item returned by `OrderedDict.popitem(last=False)`.
    try:
        # Try the fast path: an OrderedDict
        return self._data.popitem(last=False)
    except AttributeError:
        # `_data` does not exist or is not an OrderedDict
        # Attempt to use a separate order list
        if not hasattr(self, "_order") or not self._order:
            raise KeyError("popitem(): dictionary is empty")
        key = self._order.pop(0)
        try:
            value = self._data.pop(key)
        except Exception as exc:
            # If the key is missing from the underlying dict, raise KeyError
            raise KeyError(f"Key {key!r} not found in cache") from exc
        return key, value
    except KeyError:
        # The underlying OrderedDict is empty
        raise KeyError("popitem(): dictionary is empty")
    except Exception as exc:
        # Any other unexpected error
        raise RuntimeError("Unexpected error during popitem") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Attempt to pop the most recently used item.
        # If the class inherits from dict or OrderedDict, super().popitem()
        # will remove the last inserted/used item.
        return super().popitem()
    except KeyError as exc:
        # The underlying container is empty; raise a clear error.
        raise KeyError("popitem(): dictionary is empty") from exc
    except Exception as exc:
        # Catch any unexpected errors and re-raise with context.
        raise RuntimeError("An unexpected error occurred while popping an item") from exc

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        if not self:
            raise KeyError('dictionary is empty')
        import random
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)
    except AttributeError:
        raise TypeError('popitem() requires a mapping object')
    except KeyError:
        raise

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches the keyword IN followed by optional whitespace and a parenthesized
        # list of values, e.g., "IN (1, 2, 3)". The pattern is case-insensitive.
        return re.compile(r'\bIN\s*\(([^)]*)\)', re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style parameter regex: {exc}") from exc

def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Handle dictionary-like requests
        if isinstance(request, dict):
            # Check public message
            pub = request.get('public')
            if isinstance(pub, dict):
                if pub.get('type') == 'diaspora' or pub.get('diaspora') is not None:
                    return True
            elif pub is not None:
                return True

            # Check private message
            priv = request.get('private')
            if isinstance(priv, dict):
                if priv.get('type') == 'diaspora_private' or priv.get('diaspora') is not None:
                    return True
            elif priv is not None:
                return True

            # Check legacy payload
            legacy = request.get('legacy')
            if isinstance(legacy, dict):
                if legacy.get('legacy') is True:
                    return True
            elif legacy is not None:
                return True

            return False

        # Handle object-like requests
        if hasattr(request, 'public'):
            pub = getattr(request, 'public')
            if isinstance(pub, dict):
                if pub.get('type') == 'diaspora' or pub.get('diaspora') is not None:
                    return True
            elif pub is not None:
                return True

        if hasattr(request, 'private'):
            priv = getattr(request, 'private')
            if isinstance(priv, dict):
                if priv.get('type') == 'diaspora_private' or priv.get('diaspora') is not None:
                    return True
            elif priv is not None:
                return True

        if hasattr(request, 'legacy'):
            legacy = getattr(request, 'legacy')
            if isinstance(legacy, dict):
                if legacy.get('legacy') is True:
                    return True
            elif legacy is not None:
                return True

        return False
    except Exception:
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Handle None or non-object inputs
    if request is None:
        return False

    # Try to obtain a dictionary representation of the request
    if isinstance(request, dict):
        data = request
    else:
        try:
            data = request.__dict__
        except Exception:
            return False

    # Helper to fetch a value from the data structure
    def _get(key: str):
        if isinstance(data, dict):
            return data.get(key)
        return getattr(request, key, None)

    # Count how many typical Matrix event keys are present
    typical_keys = ["type", "content", "room_id", "event_id", "sender", "origin", "origin_server_ts"]
    present_count = sum(1 for k in typical_keys if _get(k) is not None)
    if present_count >= 3:
        return True

    # Check individual fields for Matrix-specific patterns
    t = _get("type")
    if isinstance(t, str) and t.startswith("m."):
        return True

    rid = _get("room_id")
    if isinstance(rid, str) and rid.startswith("!"):
        return True

    eid = _get("event_id")
    if isinstance(eid, str) and eid.startswith("$"):
        return True

    sender = _get("sender")
    if isinstance(sender, str) and sender.startswith("@"):
        return True

    origin = _get("origin")
    if isinstance(origin, str) and "matrix" in origin.lower():
        return True

    ts = _get("origin_server_ts")
    if isinstance(ts, int):
        return True

    # Inspect the content field for typical Matrix content
    content = _get("content")
    if isinstance(content, dict):
        msgtype = content.get("msgtype")
        if isinstance(msgtype, str) and msgtype.startswith("m."):
            return True
        if "body" in content and isinstance(content["body"], str):
            return True
        if "format" in content and isinstance(content["format"], str):
            return True
        if "formatted_body" in content and isinstance(content["formatted_body"], str):
            return True
        if "m.relates_to" in content and isinstance(content["m.relates_to"], dict):
            return True
        if "m.new_content" in content and isinstance(content["m.new_content"], dict):
            return True

    # If the request has a json() method, try to inspect its output
    if hasattr(request, "json"):
        try:
            json_data = request.json()
            if isinstance(json_data, dict):
                # Avoid infinite recursion by not reusing the same object
                if json_data is not request:
                    return identify_request(json_data)
        except Exception:
            pass

    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    # Try to format the base datetime part
    try:
        base = dt.strftime("%Y-%m-%dT%H:%M:%S")
    except Exception as exc:
        raise TypeError("dt must be a datetime-like object") from exc
    # Determine timezone offset if available
    try:
        offset = dt.utcoffset()
    except Exception:
        offset = None
    if offset is None:
        return base
    total_seconds = offset.total_seconds()
    if total_seconds == 0:
        return base + "Z"
    sign = '+' if total_seconds >= 0 else '-'
    abs_seconds = abs(int(total_seconds))
    hours = abs_seconds // 3600
    minutes = (abs_seconds % 3600) // 60
    return f"{base}{sign}{hours:02d}:{minutes:02d}"

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    if not isinstance(url, str) or not url:
        return None
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Handle None input gracefully
    if node is None:
        return {}

    # Ensure the node is an XML element that can be iterated over
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("Provided node must be an XML element with iterable children") from exc

    result = {}
    for child in children:
        # Only consider elements that have a tag attribute
        tag = getattr(child, "tag", None)
        if tag is not None:
            # If multiple children share the same tag, the last one will overwrite previous ones
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if document_path is not None and not isinstance(document_path, str):
        raise ValueError("document_path must be a string if provided")

    # Normalize base URL: strip trailing slash
    base = url.rstrip('/')

    # Determine the NodeInfo document path
    if document_path is None:
        path = "/nodeinfo/2.0.json"
    else:
        # Ensure path starts with a slash
        path = document_path if document_path.startswith('/') else '/' + document_path

    # Construct the absolute href
    href = base + path

    # Build the well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    Returns True if the signature is valid, False otherwise.
    """
    # Import necessary modules inside the function to avoid top-level imports
    try:
        import base64
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.exceptions import InvalidSignature
    except Exception:
        # If cryptography or base64 is not available, we cannot verify
        return False

    # Validate input types
    if not isinstance(public_key, (bytes, str)):
        return False
    if not isinstance(doc, (bytes, str)):
        return False
    if not isinstance(signature, (bytes, str)):
        return False

    # Convert inputs to bytes
    try:
        if isinstance(public_key, str):
            public_key_bytes = public_key.encode('utf-8')
        else:
            public_key_bytes = public_key

        if isinstance(doc, str):
            doc_bytes = doc.encode('utf-8')
        else:
            doc_bytes = doc

        if isinstance(signature, str):
            # Remove whitespace and decode base64
            signature_clean = ''.join(signature.split())
            signature_bytes = base64.b64decode(signature_clean)
        else:
            signature_bytes = signature
    except Exception:
        # Any conversion error results in a failed verification
        return False

    # Load the public key
    try:
        pub_key = serialization.load_pem_public_key(public_key_bytes)
    except Exception:
        return False

    # Verify the signature
    try:
        pub_key.verify(
            signature_bytes,
            doc_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except InvalidSignature:
        return False
    except Exception:
        # Any other error (e.g., wrong key type) results in failure
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")
    doc = document.strip()
    # Try JSON first
    try:
        json_module = __import__('json')
        data = json_module.loads(doc)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get('subject')
        aliases = data.get('aliases', [])
        if aliases is None:
            aliases = []
        links = data.get('links', [])
        if links is None:
            links = []
        if not isinstance(aliases, list):
            aliases = [aliases]
        if not isinstance(links, list):
            links = [links]
        return {'subject': subject, 'aliases': aliases, 'links': links}
    except Exception:
        # Fallback to XRD (XML)
        try:
            ET = __import__('xml.etree.ElementTree', fromlist=['ElementTree'])
            root = ET.fromstring(doc)
            ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
            subject_elem = root.find('xrd:Subject', ns)
            subject = subject_elem.text if subject_elem is not None else None
            alias_elems = root.findall('xrd:Alias', ns)
            aliases = [e.text for e in alias_elems if e.text]
            link_elems = root.findall('xrd:Link', ns)
            links = []
            for le in link_elems:
                link = {}
                for attr in ['rel', 'type', 'href', 'template', 'title']:
                    if attr in le.attrib:
                        link[attr] = le.attrib[attr]
                if link:
                    links.append(link)
            return {'subject': subject, 'aliases': aliases, 'links': links}
        except Exception as e:
            raise ValueError("Failed to parse webfinger document") from e

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate input
    if not isinstance(handle, str):
        return {}
    handle = handle.strip()
    if not handle or '@' not in handle:
        return {}
    domain = handle.split('@', 1)[1].strip()
    if not domain:
        return {}

    try:
        import urllib.request
        import urllib.parse
        import json

        resource = f'acct:{handle}'
        query = urllib.parse.urlencode({'resource': resource})
        url = f"https://{domain}/.well-known/webfinger?{query}"
        req = urllib.request.Request(url, headers={'Accept': 'application/jrd+json, application/json'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.getcode() != 200:
                return {}
            data = resp.read().decode('utf-8', errors='replace')
        result = json.loads(data)
        if isinstance(result, dict):
            return result
        return {}
    except Exception:
        return {}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        import requests
        # Basic validation
        if not isinstance(url, str) or not url:
            raise ValueError("url must be a non-empty string")
        if not isinstance(method, str):
            raise ValueError("method must be a string")
        if not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be a number")
        # Send request
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as e:
        return (None, e)

try:
