def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Import yaml lazily to avoid unnecessary dependency if not used
        try:
            import yaml
        except Exception as exc:
            raise IRValidatorException(f"YAML parser not available: {exc}")

        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        # If the content is a string, attempt to parse it as YAML
        if isinstance(spec_content, str):
            try:
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML content: {exc}")
        elif isinstance(spec_content, (bytes, bytearray)):
            try:
                data = yaml.safe_load(spec_content.decode('utf-8'))
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML content: {exc}")
        else:
            # Assume it's already a Python object (e.g., dict)
            data = spec_content

        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a mapping (dictionary)")

        # Define the mandatory fields expected in the spec
        required_fields = ["name", "version", "description", "spec"]
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in spec: {', '.join(missing)}"
            )

        return data

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("yaml_file must be provided")
        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError:
            raise IRValidatorException(f"File not found: {yaml_file}")
        except Exception as exc:
            raise IRValidatorException(f"Error reading YAML file: {exc}")
        if data is None:
            raise IRValidatorException("YAML file is empty or contains no data")
        if not isinstance(data, dict):
            raise IRValidatorException("YAML file must contain a dictionary at the top level")
        required = getattr(cls, "REQUIRED_FIELDS", None)
        if required:
            missing = [field for field in required if field not in data]
            if missing:
                raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
        return data

def get_deprecated_args(self):
    """Return a dictionary mapping deprecated argument names to the new argument names they replace."""
    try:
        # Define mapping of deprecated arguments to their replacements
        deprecated_args = {
            # Example deprecated arguments
            'old_option': 'new_option',
            'old_flag': 'new_flag',
            'legacy_mode': 'modern_mode',
        }
        return deprecated_args
    except Exception:
        # If any error occurs, return an empty dictionary
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Treat None as empty dict
    if cli_args is None:
        cli_args = {}
    if answer_file_args is None:
        answer_file_args = {}

    # Validate input types
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve deprecated arguments set from the instance if available
    deprecated = getattr(self, "DEPRECATED_ARGS", set())
    if not isinstance(deprecated, (set, list, tuple)):
        deprecated = set()
    else:
        # Ensure all entries are strings
        deprecated = {str(item) for item in deprecated if isinstance(item, str)}

    # Find deprecated keys in CLI and answer file arguments
    cli_deprecated = {k for k in cli_args if k in deprecated}
    ans_deprecated = {k for k in answer_file_args if k in deprecated}

    # Combine and sort for deterministic output
    all_deprecated = sorted(cli_deprecated | ans_deprecated)

    for key in all_deprecated:
        if key in cli_deprecated and key in ans_deprecated:
            print(f"Deprecated argument '{key}' found in both CLI and answer file; CLI value will override.")
        elif key in cli_deprecated:
            print(f"Deprecated argument '{key}' found in CLI.")
        else:
            print(f"Deprecated argument '{key}' found in answer file.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")

    # The parser options are expected to be stored in a dictionary
    # mapping command names to their option specifications.
    # This attribute may be named differently depending on the
    # surrounding code; we try a few common names.
    options_source = None
    for attr in ("_parser_options", "parser_options", "options"):
        if hasattr(self, attr):
            options_source = getattr(self, attr)
            break

    if options_source is None:
        raise AttributeError("No parser options attribute found on the object")

    # Ensure the source is a mapping
    if not isinstance(options_source, dict):
        raise TypeError("Parser options source must be a dictionary")

    # Retrieve the options for the requested command
    try:
        command_options = options_source[command_name]
    except KeyError:
        raise ValueError(f"Unknown command name: {command_name!r}")

    # The options may be stored as a list, tuple, set, or any iterable.
    # Convert to a list for consistency.
    if isinstance(command_options, (list, tuple, set)):
        return list(command_options)
    try:
        return list(command_options)
    except TypeError:
        raise TypeError(f"Options for command {command_name!r} are not iterable")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    # Ensure args is a dict for lookup; if not, treat as empty
    if not isinstance(args, dict):
        args = {}
    # Build a context for evaluating string conditions
    eval_context = {"command_name": command_name, "args": args}
    eval_context.update(args)
    for opt in options_spec:
        if not isinstance(opt, dict):
            continue
        if "required_when" not in opt:
            continue
        cond = opt["required_when"]
        matched = False
        try:
            if callable(cond):
                # If the condition is a callable, call it with the args dict
                matched = bool(cond(args))
            elif isinstance(cond, dict):
                # If the condition is a dict, all key/value pairs must match
                matched = all(args.get(k) == v for k, v in cond.items())
            elif isinstance(cond, (list, tuple)):
                # If the condition is a list/tuple, all elements must evaluate to True
                matched = all(
                    bool(
                        (c(args) if callable(c) else eval(c, {}, eval_context))
                    )
                    for c in cond
                )
            else:
                # Assume the condition is a string expression
                matched = bool(eval(str(cond), {}, eval_context))
        except Exception:
            # If evaluation fails, treat as not matched
            matched = False
        if matched:
            name = opt.get("name")
            if name:
                required.append(name)
    return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        :raises TypeError: If args is not a mapping or a value does not support len().
        :raises ValueError: If an argument exceeds its specified maximum length.
        """
        # Ensure args is a mapping (dict-like)
        if not isinstance(args, dict):
            raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

        # Ensure the validator has a mapping of max lengths
        if not hasattr(self, "max_lengths"):
            raise AttributeError("Validator instance lacks 'max_lengths' attribute")

        max_lengths = getattr(self, "max_lengths")
        if not isinstance(max_lengths, dict):
            raise TypeError(f"'max_lengths' should be a dict, got {type(max_lengths).__name__}")

        for key, value in args.items():
            # Skip keys that have no length constraint
            if key not in max_lengths:
                continue

            max_len = max_lengths[key]
            if not isinstance(max_len, int) or max_len < 0:
                raise ValueError(f"Maximum length for '{key}' must be a non-negative integer, got {max_len}")

            # None values are considered valid (no length to check)
            if value is None:
                continue

            # Ensure the value supports len()
            try:
                length = len(value)
            except Exception as exc:
                raise TypeError(f"Value for '{key}' does not support len(): {exc}") from exc

            if length > max_len:
                raise ValueError(
                    f"Argument '{key}' exceeds maximum length of {max_len} (actual length: {length})"
                )
        # If all checks pass, return True for convenience
        return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Retrieve the mapping of argument names to allowed choices
    choices_map = getattr(self, 'choices', None)
    if choices_map is None:
        # No choices defined; nothing to validate
        return
    if not isinstance(choices_map, dict):
        raise TypeError(f"self.choices must be a dict, got {type(choices_map).__name__}")
    for key, value in args.items():
        if key not in choices_map:
            continue
        allowed = choices_map[key]
        if allowed is None:
            continue
        # Ensure allowed is iterable and not a string
        if isinstance(allowed, (str, bytes)):
            raise TypeError(f"Allowed choices for argument '{key}' cannot be a string")
        try:
            if value not in allowed:
                raise ValueError(f"Invalid value for argument '{key}': {value}. Allowed choices: {allowed}")
        except TypeError as exc:
            # This can happen if 'allowed' is not iterable or 'value' is unhashable
            raise TypeError(f"Error validating argument '{key}': {exc}") from exc

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine minimum and maximum values from the instance or args dict
    min_val = getattr(self, 'min', None)
    if min_val is None:
        min_val = getattr(self, 'min_value', None)
    max_val = getattr(self, 'max', None)
    if max_val is None:
        max_val = getattr(self, 'max_value', None)

    # If args is a dict and contains 'min'/'max', override the values
    if isinstance(args, dict):
        if 'min' in args:
            min_val = args['min']
        if 'max' in args:
            max_val = args['max']

    # Validate that min and max are defined and numeric
    if min_val is None or max_val is None:
        raise ValueError("Minimum and maximum values must be defined.")
    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
        raise TypeError("Minimum and maximum values must be numeric.")
    if min_val > max_val:
        raise ValueError("Minimum value cannot be greater than maximum value.")

    # Helper to validate a single numeric value
    def _check_value(val):
        if isinstance(val, bool):
            # bool is a subclass of int; treat as non-numeric for validation
            return
        if isinstance(val, (int, float)):
            if not (min_val <= val <= max_val):
                raise ValueError(f"Value {val} is out of bounds [{min_val}, {max_val}].")
        # Non-numeric values are ignored

    # Validate the provided arguments
    if args is None:
        raise ValueError("Arguments cannot be None.")

    if isinstance(args, dict):
        for key, val in args.items():
            if key in ('min', 'max'):
                continue
            _check_value(val)
    elif isinstance(args, (list, tuple, set)):
        for val in args:
            _check_value(val)
    else:
        # Single value
        _check_value(args)

    return True

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Validate input types
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list of command line arguments")
    if vars_dict is not None and not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict or None")

    # Build the command
    cmd = ["ansible-playbook"] + cli_args
    if vars_dict:
        import json
        try:
            extra = json.dumps(vars_dict)
        except (TypeError, ValueError) as e:
            raise ValueError(f"vars_dict could not be serialized to JSON: {e}")
        cmd += ["--extra-vars", extra]

    # Optionally add inventory from the workspace if available
    if hasattr(ir_workspace, "inventory_path"):
        inventory = getattr(ir_workspace, "inventory_path")
        if inventory:
            cmd += ["--inventory", inventory]

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
        return {
            "returncode": result.returncode,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "cmd": result.args,
        }
    except FileNotFoundError as e:
        # ansible-playbook binary not found
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": f"ansible-playbook not found: {e}",
            "cmd": cmd,
        }
    except Exception as e:
        # Generic error handling
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": f"Error running ansible-playbook: {e}",
            "cmd": cmd,
        }

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory does not exist: {plugin_dir}")

    # Find the plugin spec file (yaml or json)
    spec_file = None
    for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec file
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                data = json.load(f)
            else:
                if yaml is None:
                    raise ImportError("PyYAML is required to parse YAML plugin spec")
                data = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from {spec_file}: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec must be a dictionary")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(data)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate input types
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    # Validate non-empty values
    if root == "":
        raise ValueError("root cannot be empty")
    if path == "":
        raise ValueError("path cannot be empty")
    # Ensure path starts with root
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    # If root is not the root directory "/" and does not end with a slash,
    # ensure that the next character in path is a slash or that the path ends.
    if root != "/" and not root.endswith("/") and len(path) > len(root):
        if path[len(root)] != "/":
            raise ValueError(f"Path '{path}' does not start with root '{root}'")
    # Remove the root prefix
    remainder = path[len(root):]
    # Strip a leading slash from the remainder, if present
    if remainder.startswith("/"):
        remainder = remainder[1:]
    return remainder
